# Let me find the 2D connected components (regions)
def find_connected_components(grid):
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    regions = []

    for r in range(rows):
        for c in range(cols):
            if not visited[r][c]:
                # BFS to find connected component with same value
                region = {'val': grid[r][c], 'cells': [], 'visited': []}
                queue = [(r, c)]
                while queue:
                    curr_r, curr_c = queue.pop(0)
                    if visited[curr_r][curr_c]:
                        continue
                    visited[curr_r][curr_c] = True
                    region['cells'].append((curr_r, curr_c))

                    # Check 4 neighbors
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if not visited[nr][nc] and grid[nr][nc] == grid[r][c]:
                                queue.append((nr, nc))
                regions.append(region)

    return regions

