# Let me implement the SIMPLE rule: uniform horizontal run + left boundary = 8 → fill with 4s
# Then count mismatches

from copy import deepcopy

def estimate_transform(grid):
    """Apply the rule: uniform horizontal run with left boundary = 8 gets filled with 4s"""
    result = [row[:] for row in grid]  # Deep copy

    for r in range(len(result)):
        c = 0
        while c < len(result[r]):
            start_c = c
            val = result[r][c]

            # Extend run while uniform
            while c < len(result[r]) and result[r][c] == val:
                c += 1
            end_c = c
            width = end_c - start_c

            # If it's a run of at least 2 cells, check left boundary
            if width >= 2 and start_c > 0:
                left_boundary_val = result[r][start_c - 1]
                if left_boundary_val == 8:
                    # Fill entire run with 4s
                    for cc in range(start_c, end_c):
                        result[r][cc] = 4
            else:
                c += 1

    return result

# Test on demo
demo_pred = estimate_transform(demo_in)

